do local Rayfield=loadstring(game:HttpGet("https://sirius.menu/rayfield"))();local Window=Rayfield:CreateWindow({Name="Grow a Garden | V1",LoadingTitle="by Coconut (Blue Archive) | User: BQL_COCONUT",ConfigurationSaving={Enabled=false}});_G.AutoFarm=false;_G.AutoFeed=false;_G.AutoBuyEgg=false;_G.AutoBuySeed=false;_G.AutoBuyGear=false;_G.ESPEnabled=false;_G.AntiAFK=true;_G.FlyEnabled=false;_G.FlySpeed=50;_G.FarmDistance=55;_G.ESPCache={};_G.PetLookupTable={};_G.SelectedPets={};_G.SelectedSeeds={};_G.SelectedGears={};_G.SelectedEggs={};_G.SelectedTreat="Medium Treat";local player=game.Players.LocalPlayer;local ReplicatedStorage=game:GetService("ReplicatedStorage");local GameEvents=ReplicatedStorage:WaitForChild("GameEvents");local petRemote=GameEvents:WaitForChild("ActivePetService");local seedRemote=GameEvents:WaitForChild("BuySeedStock");local gearRemote=GameEvents:WaitForChild("BuyGearStock");local PetTab=Window:CreateTab("Pets & Eggs",4483362458);PetTab:CreateSection("ESP PET ID");PetTab:CreateToggle({Name="ID PET",CurrentValue=false,Callback=function(Value) _G.ESPEnabled=Value;for _,gui in pairs(_G.ESPCache) do if gui then gui.Enabled=Value;end end end});PetTab:CreateSection("AUTO BUY EGG");PetTab:CreateDropdown({Name="Select Egg Type:",Options={"Common Egg","Uncommon Egg","Rare Egg","Legendary Egg","Mythical Egg","Bug Egg","Jungle Egg"},MultipleOptions=true,Callback=function(Options) _G.SelectedEggs=Options;end});PetTab:CreateToggle({Name="Enable Auto Buy Eggs",CurrentValue=false,Callback=function(Value) _G.AutoBuyEgg=Value;task.spawn(function() while _G.AutoBuyEgg do for _,egg in pairs(_G.SelectedEggs) do pcall(function() local args={egg};ReplicatedStorage.GameEvents.BuyPetEgg:FireServer(unpack(args));end);end task.wait(0.5);end end);end});PetTab:CreateSection("AUTO FEED PET");PetTab:CreateDropdown({Name="Select Treat Type:",Options={"Medium Treat","Large Treat","Levelup Lollipop"},CurrentOption="Medium Treat",Callback=function(Option) _G.SelectedTreat=Option;end});local PetDropdown=PetTab:CreateDropdown({Name="Select Pets to Feed:",Options={"Scan Pets first"},MultipleOptions=true,Callback=function(Options) _G.SelectedPets=Options;end});PetTab:CreateButton({Name="SCAN PETS & UPDATE ESP",Callback=function() local list={};_G.PetLookupTable={};for _,v in pairs(_G.ESPCache) do if v then v:Destroy();end end _G.ESPCache={};for _,obj in pairs(game.Workspace:GetDescendants()) do if (obj:IsA("Model") and string.match(obj.Name,"%w%w%w%w%w%w%w%w%-")) then local fullID=obj.Name;local species=obj:GetAttribute("Species") or "Pet" ;local shortID=string.sub(fullID, -5);local displayName=species   .. " [#"   .. shortID   .. "]" ;_G.PetLookupTable[displayName]=fullID;table.insert(list,displayName);local bbg=Instance.new("BillboardGui");bbg.Parent=obj;bbg.Adornee=obj:FindFirstChild("HumanoidRootPart") or obj.PrimaryPart ;bbg.Size=UDim2.new(0,80,0,30);bbg.StudsOffset=Vector3.new(0,3,0);bbg.AlwaysOnTop=true;bbg.Enabled=_G.ESPEnabled;local txt=Instance.new("TextLabel",bbg);txt.Size=UDim2.new(1,0,1,0);txt.BackgroundTransparency=1;txt.TextColor3=Color3.fromRGB(0,255,255);txt.TextStrokeTransparency=0;txt.Text="ID: "   .. shortID ;txt.Font=Enum.Font.GothamBold;txt.TextSize=12;table.insert(_G.ESPCache,bbg);end end PetDropdown:Refresh(list);end});PetTab:CreateToggle({Name="Enable Auto Feed",CurrentValue=false,Callback=function(Value) _G.AutoFeed=Value;task.spawn(function() while _G.AutoFeed do for _,pName in pairs(_G.SelectedPets) do local id=_G.PetLookupTable[pName];if id then pcall(function() petRemote:FireServer("Feed",id,_G.SelectedTreat);end);end end task.wait(1.5);end end);end});local FarmTab=Window:CreateTab("Farm",4483362458);_G.FarmMode="Fast";_G.LastSellTime=tick();FarmTab:CreateDropdown({Name="Chá»n Cháº¿ Äá»™ Farm",Options={"Fast","Teleport","Fast/Teleport"},CurrentOption={"Fast"},MultipleOptions=false,Flag="DropdownFarmMode",Callback=function(Option) _G.FarmMode=Option[1];end});FarmTab:CreateSlider({Name="Farm (Studs)",Range={10,150},