sition-itemPos).Magnitude;if (distanceToPlayer<=_G.FarmDistance) then fireproximityprompt(obj);elseif ((distanceToPlayer>_G.FarmDistance) and (distanceToPlayer<=100)) then root.CFrame=CFrame.new(itemPos + Vector3.new(0,2,0) );task.wait(0.15);fireproximityprompt(obj);task.wait(0.1);end end end end task.wait(0.2);end end end);end});local ShopTab=Window:CreateTab("Shop",4483362458);ShopTab:CreateSection("AUTO BUY SEEDS");ShopTab:CreateDropdown({Name="Select Seeds:",Options={"Carrot [Common]","Strawberry [Common]","Blueberry [Uncommon]","Buttercup [Uncommon]","Tomato [Rare]","Corn [Rare]","Daffodil [Rare]","Watermelon [Legendary]","Pumpkin [Legendary]","Apple [Legendary]","Bamboo [Legendary]","Coconut [Mythical]","Cactus [Mythical]","Dragon Fruit [Mythical]","Mango [Mythical]","Grape [Divine]","Mushroom [Divine]","Pepper [Divine]","Cacao [Divine]","Sunflower [Divine]","Beanstalk [Prismatic]","Ember Lily [Prismatic]","Sugar Apple [Prismatic]","Burning Bud [Prismatic]","Elder Strawberry [Prismatic]","Romanesco [Prismatic]","Crimson Thorn [Transcendent]","Zebrazinkle [Transcendent]","Octobloom [Transcendent]","Alien Apple [Transcendent]"},MultipleOptions=true,Callback=function(Options) _G.SelectedSeeds={};for _,v in pairs(Options) do local rawName=string.split(v," [")[1];table.insert(_G.SelectedSeeds,rawName);end end});ShopTab:CreateToggle({Name="Enable Auto Buy Seeds",CurrentValue=false,Callback=function(Value) _G.AutoBuySeed=Value;task.spawn(function() while _G.AutoBuySeed do if ( #_G.SelectedSeeds>0) then for _,seedName in pairs(_G.SelectedSeeds) do pcall(function() local args={"Shop",seedName};seedRemote:FireServer(unpack(args));end);end end task.wait(0.5);end end);end});ShopTab:CreateSection("AUTO BUY GEAR");ShopTab:CreateDropdown({Name="Select Gear:",Options={"Watering Can","Basic Sprinkler","Advanced Sprinkler","Godly Sprinkler","Master Sprinkler","Grandmaster Sprinkler","Supreme Sprinkler","Harvest Tool","Trowel","Recall Wrench","Cleaning Spray","Pet Lead","Favorite Tool","Trading Ticket","Levelup Lollipop"},MultipleOptions=true,Callback=function(Options) _G.SelectedGears=Options;end});ShopTab:CreateToggle({Name="Enable Auto Buy Gears",CurrentValue=false,Callback=function(Value) _G.AutoBuyGear=Value;task.spawn(function() while _G.AutoBuyGear do for _,gear in pairs(_G.SelectedGears) do pcall(function() gearRemote:FireServer(gear);end);end task.wait(0.5);end end);end});local SettingTab=Window:CreateTab("Settings",4483362458);SettingTab:CreateSection("CHARACTER");SettingTab:CreateSlider({Name="WalkSpeed",Range={16,250},Increment=1,Suffix="Speed",CurrentValue=16,Callback=function(Value) player.Character.Humanoid.WalkSpeed=Value;end});SettingTab:CreateSlider({Name="JumpPower",Range={50,500},Increment=1,Suffix="Power",CurrentValue=50,Callback=function(Value) player.Character.Humanoid.UseJumpPower=true;player.Character.Humanoid.JumpPower=Value;end});SettingTab:CreateSection("MOVEMENT");SettingTab:CreateToggle({Name="Fly (Bay)",CurrentValue=false,Callback=function(Value) _G.FlyEnabled=Value;if Value then local char=player.Character;local root=char:FindFirstChild("HumanoidRootPart");local camera=workspace.CurrentCamera;task.spawn(function() local bv=Instance.new("BodyVelocity",root);bv.MaxForce=Vector3.new(math.huge,math.huge,math.huge);bv.Velocity=Vector3.new(0,0,0);while _G.FlyEnabled do local moveDir=char.Humanoid.MoveDirection;bv.Velocity=(camera.CFrame.LookVector * (((moveDir.Magnitude>0) and _G.FlySpeed) or 0)) + Vector3.new(0,0.1,0) ;task.wait();end bv:Destroy();end);end end});SettingTab:CreateSlider({Name="Fly Speed",Range={10,300},Increment=5,Suffix="Speed",CurrentValue=50,Callback=function(Value) _G.FlySpeed=Value;end});SettingTab:CreateSection("MISC");SettingTab:CreateToggle({Name="Anti-AFK",CurrentValue=true,Callback=function(Value) _G.AntiAFK=Value;end});local VU=game:GetService("VirtualUser");player.Idled:Connect(function() if _G.AntiAFK then VU:CaptureController();VU:ClickButton2(Vector2.new());end end);Rayfield:Notify(